export interface AlphaMachineImage_SourceInstanceProperties {
  /** Enables instances created based on this machine image to send packets with source IP addresses other than their own and receive packets with destination IP addresses other than their own. If these instances will be used as an IP gateway or it will be set as the next-hop in a Route resource, specify true. If unsure, leave this set tofalse. See theEnable IP forwarding documentation for more information. */
  canIpForward?: boolean | Computed<boolean>;
  /** Whether the instance created from this machine image should be protected against deletion. */
  deletionProtection?: boolean | Computed<boolean>;
  /** An optional text description for the instances that are created from this machine image. */
  description?: string | Computed<string>;
  /** An array of disks that are associated with the instances that are created from this machine image. */
  disks?: AlphaMachineImage_SourceInstanceProperties_Disks[] | Computed<AlphaMachineImage_SourceInstanceProperties_Disks[]>;
  /** A list of guest accelerator cards' type and count to use for instances created from this machine image. */
  guestAccelerators?: AlphaMachineImage_InstanceProperties_GuestAccelerators[] | Computed<AlphaMachineImage_InstanceProperties_GuestAccelerators[]>;
  /** KeyRevocationActionType of the instance. Supported options are "STOP" and "NONE". The default value is "NONE" if it is not specified. */
  keyRevocationActionType?: string | Computed<string>;
  /** Labels to apply to instances that are created from this machine image. */
  labels?: Record<string, string> | Computed<Record<string, string>>;
  /** The machine type to use for instances that are created from this machine image. */
  machineType?: string | Computed<string>;
  /** A metadata key/value entry. */
  metadata?: AlphaMachineImage_InstanceProperties_Metadata | Computed<AlphaMachineImage_InstanceProperties_Metadata>;
  /** Minimum cpu/platform to be used by instances created from this machine image. The instance may be scheduled on the specified or newer cpu/platform. Applicable values are the friendly names of CPU platforms, such as minCpuPlatform: "Intel Haswell" orminCpuPlatform: "Intel Sandy Bridge". For more information, read Specifying a Minimum CPU Platform. */
  minCpuPlatform?: string | Computed<string>;
  /** An array of network access configurations for this interface. */
  networkInterfaces?: AlphaMachineImage_InstanceProperties_NetworkInterfaces[] | Computed<AlphaMachineImage_InstanceProperties_NetworkInterfaces[]>;
  /** PostKeyRevocationActionType of the instance. */
  postKeyRevocationActionType?: string | Computed<string>;
  /** Sets the scheduling options for an Instance. */
  scheduling?: AlphaMachineImage_InstanceProperties_Scheduling | Computed<AlphaMachineImage_InstanceProperties_Scheduling>;
  /** A list of service accounts with specified scopes. Access tokens for these service accounts are available to the instances that are created from this machine image. Use metadata queries to obtain the access tokens for these instances. */
  serviceAccounts?: AlphaMachineImage_InstanceProperties_ServiceAccounts[] | Computed<AlphaMachineImage_InstanceProperties_ServiceAccounts[]>;
  /** A set of instance tags. */
  tags?: AlphaMachineImage_InstanceProperties_Tags | Computed<AlphaMachineImage_InstanceProperties_Tags>;
}

